"use server";

import { z } from "zod";
import { getTenantPrisma } from "@/lib/tenant-prisma";
import { requireSession } from "@/lib/auth/session";
import { audit } from "@/server/audit";
import { createNotification } from "@/server/notifications/create";
import { assertMatterWritable } from "@/lib/archive/guard";
import { assertCanAssociateMatter } from "@/lib/permissions";
import { matterHrefById, revalidateMatter } from "@/server/matters/route";

const taskCreateSchema = z.object({
  matterId: z.string().cuid(),
  title: z.string().min(1, "El título de la tarea es obligatorio").max(200),
  description: z.string().max(2000).optional().or(z.literal("")),
  assigneeId: z.string().cuid().optional().or(z.literal("")),
  dueAt: z.coerce.date().optional(),
  priority: z.coerce.number().int().min(0).max(2).default(0),
  stageId: z.string().cuid().optional().or(z.literal(""))
});

const taskUpdateSchema = taskCreateSchema.extend({
  id: z.string().cuid()
});

export type TaskCreateInput = z.infer<typeof taskCreateSchema>;
export type TaskUpdateInput = z.infer<typeof taskUpdateSchema>;

export async function createTask(input: TaskCreateInput) {
  const prisma = await getTenantPrisma();
  const session = await requireSession();
  const data = taskCreateSchema.parse(input);
  await assertCanAssociateMatter(session.user.id, session.user.role, data.matterId);
  await assertMatterWritable(data.matterId);

  const created = await prisma.task.create({
    data: {
      matterId: data.matterId,
      title: data.title,
      description: data.description || null,
      assigneeId: data.assigneeId || null,
      dueAt: data.dueAt,
      priority: data.priority,
      stageId: data.stageId || null
    }
  });

  await audit({
    userId: session.user.id,
    action: "TASK_CREATE",
    targetType: "Task",
    targetId: created.id,
    detail: { matterId: data.matterId, title: created.title }
  });

  // v0.43 ítem 4: escribir en la línea de tiempo del Caso
  await prisma.timelineEvent.create({
    data: {
      matterId: data.matterId,
      eventType: "TASK_ADDED",
      title: `Nueva tarea: ${created.title}`,
      occurredAt: new Date(),
      refType: "Task",
      refId: created.id
    }
  });

  // Notificaciones al asignado (cuando no es el mismo Creador)
  if (data.assigneeId && data.assigneeId !== session.user.id) {
    await createNotification({
      userId: data.assigneeId,
      type: "TASK_ASSIGNED",
      title: "Tenés una nueva tarea",
      content: `La tarea«${created.title}»te fue asignada`,
      href: await matterHrefById(data.matterId),
      refType: "Task",
      refId: created.id
    });
  }

  await revalidateMatter(data.matterId);
  const { revalidatePath: rp1 } = await import("next/cache");
  rp1("/schedule");
  return { ok: true, id: created.id };
}

export async function updateTask(input: TaskUpdateInput) {
  const prisma = await getTenantPrisma();
  const session = await requireSession();
  const data = taskUpdateSchema.parse(input);
  await assertCanAssociateMatter(session.user.id, session.user.role, data.matterId);
  await assertMatterWritable(data.matterId);
  const { id, matterId, ...rest } = data;

  await prisma.task.update({
    where: { id },
    data: {
      title: rest.title,
      description: rest.description || null,
      assigneeId: rest.assigneeId || null,
      dueAt: rest.dueAt,
      priority: rest.priority,
      stageId: rest.stageId || null
    }
  });

  // Notificar si cambió el asignado (y no es el que edita)
  const before = await prisma.task.findUnique({
    where: { id },
    select: { assigneeId: true, title: true },
  });
  
  if (
    rest.assigneeId &&
    rest.assigneeId !== session.user.id &&
    rest.assigneeId !== before?.assigneeId
  ) {
    await createNotification({
      userId: rest.assigneeId,
      type: "TASK_ASSIGNED",
      title: "Tenés una nueva tarea",
      content: `La tarea «${rest.title}» te fue asignada`,
      href: await matterHrefById(matterId),
      refType: "Task",
      refId: id,
    });
  }

  await audit({
    userId: session.user.id,
    action: "TASK_UPDATE",
    targetType: "Task",
    targetId: id
  });

  await revalidateMatter(matterId);
  const { revalidatePath: rp2 } = await import("next/cache");
  rp2("/schedule");
  return { ok: true };
}

export async function toggleTaskCompleted(id: string) {
  const prisma = await getTenantPrisma();
  const session = await requireSession();
  const current = await prisma.task.findUnique({ where: { id } });
  if (!current) return { ok: false };
  await assertCanAssociateMatter(session.user.id, session.user.role, current.matterId);
  await assertMatterWritable(current.matterId);

  const next = !current.completed;
  await prisma.task.update({
    where: { id },
    data: {
      completed: next,
      completedAt: next ? new Date() : null
    }
  });

  await audit({
    userId: session.user.id,
    action: next ? "TASK_COMPLETE" : "TASK_REOPEN",
    targetType: "Task",
    targetId: id
  });

  await revalidateMatter(current.matterId);
  
  // Invalidar caché del calendario para que la tarea completada desaparezca
  const { revalidatePath } = await import("next/cache");
  revalidatePath("/schedule");
  
  return { ok: true };
}

export async function deleteTask(id: string) {
  const prisma = await getTenantPrisma();
  const session = await requireSession();
  const current = await prisma.task.findUnique({ where: { id } });
  if (!current) return { ok: false };
  await assertCanAssociateMatter(session.user.id, session.user.role, current.matterId);
  await assertMatterWritable(current.matterId);

  await prisma.task.delete({ where: { id } });
  const { revalidatePath: rp3 } = await import("next/cache");
  rp3("/schedule");

  await audit({
    userId: session.user.id,
    action: "TASK_DELETE",
    targetType: "Task",
    targetId: id
  });

  await revalidateMatter(current.matterId);
  return { ok: true };
}